func (q *Queries) ListUpcomingRecurringRules(ctx context.Context, arg ListUpcomingRecurringRulesParams) ([]RecurringRule, error) {
	rows, err := q.db.Query(ctx, listUpcomingRecurringRules, arg.UserID, arg.NextDueDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RecurringRule
	for rows.Next() {
		var i RecurringRule
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.MerchantNorm,
			&i.AmountPaise,
			&i.Type,
			&i.Cadence,
			&i.NextDueDate,
			&i.Active,
			&i.CategoryID,
			&i.SnoozedUntil,
			&i.CancelledAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

